    const algebra = /^L(\d)(\d)_P\d$/.exec(strippedId);
    const apStats = /^APStats_(\d+)-(\d+)_P\d$/.exec(strippedId);
    const lesson = algebra
      ? `${algebra[1]}-${algebra[2]}`
      : apStats
