n\": \"5-4\", \"source\": \"Savvas Teacher Edition \u2014 HabitsOfMind (lesson 5-4, anchor Example 6)\", \"page\": null, \"image\": null, \"has_visual\": false, \"visual_type\": \"none\", \"visual_needs_cleanup\": false, \"visual_clean_asset\": null, \"prompt\": \"Make Sense and Persevere How are the steps for solving a radical inequality different from the steps for solving a radical equation?\", \"answers\": [], \"correct\": null, \"dok\": 2, \"dok_rationale\": \"Auto-assigned DOK 2 from source structure. Verify against Item Analysis.\", \"topics\": [], \"tags\": [\"lesson-5-4\", \"teacher-edition\", \"ex6-te\", \"habits-of-mind\"], \"used_in\": [], \"notes\": \"Answer key (from source): The steps for solving a radical inequality are the same as the steps for solving a radical equation. The only time they would be different is when multiplying or dividing each side of the inequality by a negative number; then you have to remember to reverse the inequality symbol.\", \"created_at\": \"2026-04-20\", \"role\": \"explore-practice\", \"standards\": [\"A-REI.A.2\", \"A-CED.A.4\"], \"prereq_ids\": [], \"rehearses\": [], \"echoes\": [], \"skill_tokens\": [\"solve-radical-equation\"]}\n 489: {\"id\": \"5-4-savvas-teacher-edition-purposefulquestio-8\", \"lesson\": \"5-4\", \"source\": \"Savvas Teacher Edition \u2014 PurposefulQuestions (lesson 5-4, anchor Example 6)\", \"page\": null, \"image\": null, \"has_visual\": false, \"visual_type\": \"none\", \"visual_needs_cleanup\": false, \"visual_clean_asset\": null, \"prompt\": \"Example 6 Help students understand how to solve real-world inequalities.\\n\\nQ: How do you know what to solve for when you are finding how high off the ground the ride should be?\", \"answers\": [], \"correct\": null, \"dok\": 2, \"dok_rationale\": \"Auto-assigned DOK 2 from source structure. Verify against Item Analysis.\", \"topics\": [], \"tags\": [\"lesson-5-4\", \"teacher-edition\", \"ex6-te\", \"purposeful-questions\"], \"used_in\": [], \"notes\